vector<int> computeLPS(const string& pattern) {
    int m = pattern.size();
    vector<int> lps(m, 0);
    int len = 0;   // length of the current matched prefix that is also a suffix
    int i = 1;

    while (i < m) {
        if (pattern[i] == pattern[len]) {
            len++;
            lps[i] = len;
            i++;
        } else if (len != 0) {
            len = lps[len - 1];   // fall back using LPS itself, do NOT reset to 0
        } else {
            lps[i] = 0;
            i++;
        }
    }
    return lps;
}

