vector<int> kmpSearch(const string& text, const string& pattern) {
    int n = text.size();
    int m = pattern.size();
    vector<int> matches;
    if (m == 0 || m > n) return matches;

    vector<int> lps = computeLPS(pattern);

    int i = 0;   // pointer into text, NEVER moves backward
    int j = 0;   // pointer into pattern

    while (i < n) {
        if (text[i] == pattern[j]) {
            i++;
            j++;
            if (j == m) {
                matches.push_back(i - j);   // match starts here
                j = lps[j - 1];             // keep going, allow overlapping matches
            }
        } else if (j != 0) {
            j = lps[j - 1];   // fall back the pattern pointer, i stays put
        } else {
            i++;              // no partial match to fall back on
        }
    }
    return matches;
}

int main() {
    string text = "ABABABCABABABCABAB";
    string pattern = "ABABAC";

    vector<int> hits = kmpSearch(text, pattern);
    for (int idx : hits) {
        cout << "Match at index " << idx << "\n";
    }
    return 0;
}
